function validate([m, n, horizontalCut, verticalCut]) {
  if (!Number.isInteger(m) || !Number.isInteger(n) || m < 1 || m > 20 || n < 1 || n > 20) return 'm and n are whole numbers from 1 to 20.';
  if (!Array.isArray(horizontalCut) || horizontalCut.length !== m - 1) return 'horizontalCut needs exactly m - 1 costs.';
  if (!Array.isArray(verticalCut) || verticalCut.length !== n - 1) return 'verticalCut needs exactly n - 1 costs.';
  if ([...horizontalCut, ...verticalCut].some(c => !Number.isInteger(c) || c < 1 || c > 1000)) return 'Each cost is a whole number from 1 to 1000.';
  return null;
}

