function minimumCost(m, n, horizontalCut, verticalCut) {
  const horizontal = [...horizontalCut].sort((a, b) => b - a);
  const vertical = [...verticalCut].sort((a, b) => b - a);
  let h = 0;
  let v = 0;
  let total = 0;

  while (h < horizontal.length || v < vertical.length) {
    if (v === vertical.length || (h < horizontal.length && horizontal[h] >= vertical[v])) {
      total += horizontal[h] * (v + 1);
      h++;
    } else {
      total += vertical[v] * (h + 1);
      v++;
    }
  }
  return total;
}

