function minimumCost(m, n, horizontalCut, verticalCut) {
  // Cheapest way to cut the block of rows r1..r2 and columns c1..c2 into unit squares, trying every first cut.
  const memo = new Int32Array(m * m * n * n).fill(-1);
  const solve = (r1, r2, c1, c2) => {
    if (r1 === r2 && c1 === c2) return 0;
    const key = ((r1 * m + r2) * n + c1) * n + c2;
    if (memo[key] >= 0) return memo[key];
    let best = Infinity;
    for (let line = r1; line < r2; line++) best = Math.min(best, horizontalCut[line] + solve(r1, line, c1, c2) + solve(line + 1, r2, c1, c2));
    for (let line = c1; line < c2; line++) best = Math.min(best, verticalCut[line] + solve(r1, r2, c1, line) + solve(r1, r2, line + 1, c2));
    memo[key] = best;
    return best;
  };
  return solve(0, m - 1, 0, n - 1);
}

