function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const m = large ? int(16, 20) : int(1, 5);
  const n = large ? int(16, 20) : int(1, 5);
  // Small costs repeat often, so ties between the two directions get tested.
  const top = large || rand() < 0.3 ? 1000 : int(1, 6);
  const costs = length => Array.from({ length }, () => int(1, top));
  return [m, n, costs(m - 1), costs(n - 1)];
}
